sp_header_footer.client_script:
api.controller = function($scope) {
    var c = this;

    c.mobileMenuOpen = false;

    c.toggleMobileMenu = function() {
        c.mobileMenuOpen = !c.mobileMenuOpen;
    };

    c.closeMobileMenu = function() {
        c.mobileMenuOpen = false;
    };
};

sp_header_footer.css:
/* DSFR Header - Design System de l'État français */
/* Font: Marianne */
$dsfr-blue: #000091;
$dsfr-red: #E1000F;
$dsfr-text: #161616;
$dsfr-border: #E5E5E5;
$dsfr-white: #FFFFFF;
$dsfr-bg-light: #F6F6F6;
$dsfr-blue-light: #F5F5FE;

.dsfr-header {
  font-family: 'Marianne', Arial, sans-serif;
  background-color: $dsfr-white;
  position: relative;
  z-index: 1000;
}

/* Tricolore border top */
.dsfr-header__tricolore {
  height: 4px;
  background: linear-gradient(to right, $dsfr-blue 33.33%, $dsfr-white 33.33%, $dsfr-white 66.66%, $dsfr-red 66.66%);
}

/* Header body (top bar) */
.dsfr-header__body {
  min-height: 80px;
  border-bottom: 1px solid $dsfr-border;
}

.dsfr-header__body-inner {
  display: flex;
  align-items: center;
  min-height: 80px;
  width: 100%;
}

/* Brand / Logo */
.dsfr-header__brand {
  flex-shrink: 0;
  margin-right: 24px;
}

.dsfr-header__brand-link {
  text-decoration: none;
  color: $dsfr-text;
  display: block;

  &:hover,
  &:focus {
    text-decoration: none;
    color: $dsfr-text;
  }
}

.dsfr-header__logo {
  display: flex;
  align-items: center;
}

.dsfr-header__logo-img {
  height: 64px;
  width: auto;
  display: block;
}

/* Service / Portal title */
.dsfr-header__service {
  flex: 1;
  min-width: 0;
  padding-right: 16px;
}

.dsfr-header__service-title {
  font-size: 18px;
  font-weight: 700;
  color: $dsfr-text;
  text-decoration: none;
  display: block;
  line-height: 1.3;

  &:hover,
  &:focus {
    text-decoration: none;
    color: $dsfr-blue;
  }
}

.dsfr-header__service-tagline {
  font-size: 12px;
  color: #666666;
  margin: 2px 0 0 0;
  line-height: 1.3;
}

/* Tools (right section) */
.dsfr-header__tools {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  gap: 16px;
}

.dsfr-header__tools-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Buttons */
.dsfr-btn {
  display: inline-block;
  font-family: 'Marianne', Arial, sans-serif;
  font-size: 13px;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 3px;
  text-decoration: none;
  cursor: pointer;
  border: 1px solid transparent;
  line-height: 1.4;
  text-align: center;
  transition: background-color 0.2s, border-color 0.2s, color 0.2s;

  &:hover,
  &:focus {
    text-decoration: none;
  }
}

.dsfr-btn--primary {
  background-color: $dsfr-blue;
  color: $dsfr-white;
  border-color: $dsfr-blue;

  &:hover,
  &:focus {
    background-color: darken($dsfr-blue, 10%);
    color: $dsfr-white;
  }
}

.dsfr-btn--outlined {
  background-color: transparent;
  color: $dsfr-blue;
  border-color: $dsfr-blue;

  &:hover,
  &:focus {
    background-color: $dsfr-blue;
    color: $dsfr-white;
  }
}

.dsfr-btn--menu {
  background: none;
  border: none;
  font-size: 20px;
  color: $dsfr-text;
  padding: 8px 12px;

  &:hover,
  &:focus {
    color: $dsfr-blue;
  }
}

.dsfr-btn--block {
  display: block;
  width: 100%;
  margin-bottom: 8px;
}

/* User info */
.dsfr-header__user {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: $dsfr-text;
}

.dsfr-header__user-icon {
  font-size: 14px;
  color: $dsfr-blue;
}

.dsfr-header__user-name {
  white-space: nowrap;
}

/* ===== Navigation principale (icônes + soulignement bleu) ===== */
.main-nav {
  background-color: $dsfr-white;
  border-bottom: 1px solid $dsfr-border;
}

.main-nav .nav-list {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
  padding: 0;
  margin: 0;
}

.main-nav .nav-item {
  margin: 0;
}

.main-nav .nav-link {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 14px;
  font-size: 14px;
  font-weight: 600;
  color: $dsfr-blue;
  text-decoration: none;
  border-bottom: 3px solid transparent;
  white-space: nowrap;
  transition: background-color 0.2s ease, border-color 0.2s ease;

  &:hover,
  &:focus {
    background-color: $dsfr-blue-light;
    text-decoration: none;
  }
}

.main-nav .nav-link.active {
  border-bottom-color: $dsfr-blue;
}

.main-nav .nav-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

/* Sécurité : borne TOUS les svg de la nav pour éviter tout débordement */
.main-nav svg {
  width: 18px;
  height: 18px;
  max-width: 18px;
  max-height: 18px;
  flex-shrink: 0;
}

/* Mobile menu */
.dsfr-header__burger {
  margin-left: auto;
}

.dsfr-header__mobile-panel {
  background-color: $dsfr-bg-light;
  padding: 16px 0;
  border-bottom: 1px solid $dsfr-border;
}

.dsfr-header__mobile-links {
  margin-bottom: 12px;
}

.dsfr-header__mobile-user {
  font-size: 13px;
  color: $dsfr-text;
  padding: 8px 0;

  .fa {
    margin-right: 6px;
    color: $dsfr-blue;
  }
}

/* Responsive */
@media (max-width: 767px) {
  .dsfr-header__body-inner {
    padding: 0 8px;
  }

  .dsfr-header__service {
    display: none;
  }

  .main-nav {
    display: none;

    &.main-nav--open {
      display: block;
    }

    .nav-list {
      flex-direction: column;
    }

    .nav-link {
      border-bottom: none;
      border-left: 3px solid transparent;
      white-space: normal;

      &:hover,
      &:focus {
        border-left-color: $dsfr-blue;
        border-bottom-color: transparent;
      }
    }

    .nav-link.active {
      border-left-color: $dsfr-blue;
      border-bottom-color: transparent;
    }
  }
}

@media (min-width: 768px) {
  .dsfr-header__mobile-panel {
    display: none;
  }
}

sp_header_footer.script:
(function() {
    // Menu integration
    var menu = $sp.getValue("sp_rectangle_menu");
    data.menu = $sp.getWidgetFromInstance(menu);

    // Current user info
    data.userDisplayName = gs.getUserDisplayName();
    data.userID = gs.getUserID();
    data.userRoles = gs.getUser().getRoles().toString();
    data.isLoggedIn = gs.isLoggedIn();

    // Portal identification - this is the Internet portal
    data.isInternet = true;

    // Portal URLs
    data.portalInternetUrl = '/familles';
    data.portalIntradefUrl = '/habitat';
})();
